import { readdir, readFile } from "node:fs/promises";
import path from "node:path";

const EXCLUDED_DIRECTORIES = new Set([
  ".git",
  "node_modules",
  "spaced-repetition",
]);

const TEXT_EXTENSIONS = new Set([
  ".md",
  ".js",
  ".mjs",
  ".ts",
  ".tsx",
  ".cs",
  ".json",
  ".yaml",
  ".yml",
]);

function displayCue(context, index = 0) {
  return context.cues[index % context.cues.length] ?? context.title;
}

export const CARD_BLUEPRINTS = Object.freeze([
  {
    id: "orient",
    name: "Purpose and placement",
    question: context =>
      `Without opening ${context.relativePath}, explain its purpose, intended user, ` +
      `inputs, outputs, and how it connects to the rest of the track.`,
    criteria: context => [
      `Names the role suggested by “${context.title}”.`,
      "Identifies at least one upstream prerequisite and downstream use.",
      "Separates the file's responsibility from a nearby file or layer.",
      "Points to an artifact that would prove the explanation.",
    ],
  },
  {
    id: "retrieve",
    name: "No-notes reconstruction",
    question: context =>
      `Reconstruct the major ideas or behaviors in ${context.relativePath}. Begin ` +
      `with “${displayCue(context, 0)}” and recover at least four more items from memory.`,
    criteria: context => [
      `Includes the cue “${displayCue(context, 0)}” accurately.`,
      `Recovers important relationships among: ${context.cues.slice(0, 5).join(", ")}.`,
      "Does not merely repeat headings; explains why the parts matter.",
      "Marks uncertain claims before checking the source.",
    ],
  },
  {
    id: "structure",
    name: "Structure and flow",
    question: context =>
      `Draw a map, state table, call flow, or ordered outline for ${context.relativePath}. ` +
      `Explain how “${displayCue(context, 0)}” relates to “${displayCue(context, 1)}”.`,
    criteria: context => [
      "Shows direction, ownership, or sequence—not only a list.",
      "Labels a boundary where data, control, or responsibility changes.",
      "Includes one normal path and one boundary/failure path.",
      "Provides a numbered text equivalent when the artifact is visual.",
    ],
  },
  {
    id: "example",
    name: "Concrete example and counterexample",
    question: context =>
      `Create the smallest concrete example that demonstrates “${displayCue(context, 0)}” ` +
      `from ${context.relativePath}, then change one detail to create a counterexample.`,
    criteria: context => [
      "Predicts both outcomes before checking the file or running code.",
      "Changes exactly one meaningful condition between cases.",
      "States the general rule that separates the cases.",
      "Connects the rule to an executable check or inspectable artifact.",
    ],
  },
  {
    id: "implement",
    name: "Implementation or application",
    question: context =>
      `Apply one idea from ${context.relativePath} to a small change in RelayBoard or ` +
      `an executable example. Use “${displayCue(context, 1)}” as the starting cue.`,
    criteria: context => [
      "Writes an acceptance criterion before changing the implementation.",
      "Produces code, configuration, query, test, or operational evidence.",
      "Exercises a failure or invalid case in addition to success.",
      "Keeps the change focused enough for review.",
    ],
  },
  {
    id: "debug",
    name: "Failure diagnosis",
    question: context =>
      `Invent or reproduce a plausible failure related to “${displayCue(context, 2)}” ` +
      `in ${context.relativePath}. Diagnose it from competing hypotheses.`,
    criteria: context => [
      "Records the symptom separately from the suspected cause.",
      "Lists at least two hypotheses and their predicted observations.",
      "Runs the cheapest experiment that distinguishes them.",
      "Updates a mental rule and adds prevention or regression evidence.",
    ],
  },
  {
    id: "review",
    name: "Professional review",
    question: context =>
      `Review ${context.relativePath} as if inheriting it from another engineer. ` +
      `Identify one correctness risk, one maintainability question, and one missing proof.`,
    criteria: context => [
      "Restates the intended outcome before criticizing details.",
      "Grounds every concern in a line, behavior, contract, or absent artifact.",
      "Separates blocking risk from optional preference.",
      "Requests the smallest useful response or experiment.",
    ],
  },
  {
    id: "explain",
    name: "Teach-back at three depths",
    question: context =>
      `Explain ${context.title} in 30 seconds, 2 minutes, and 5 minutes without ` +
      `reading ${context.relativePath}. Include “${displayCue(context, 0)}”.`,
    criteria: context => [
      "The short version states problem, choice, and outcome.",
      "The medium version adds mechanism, tradeoff, and evidence.",
      "The deep version adds failure, alternative, and changed constraint.",
      "Facts, measurements, and assumptions remain distinguishable.",
    ],
  },
  {
    id: "transfer",
    name: "Changed-constraint transfer",
    question: context =>
      `Take the central lesson of ${context.relativePath} and change one constraint: ` +
      `scale, ordering, failure, permission, compatibility, accessibility, or ownership. ` +
      `What remains valid and what must change?`,
    criteria: context => [
      "Names the original invariant before changing the scenario.",
      "Changes one constraint clearly rather than redesigning everything.",
      "Predicts the first invalid assumption or bottleneck.",
      "Proposes evidence that would justify the smallest adaptation.",
    ],
  },
  {
    id: "synthesize",
    name: "Delayed synthesis",
    question: context =>
      `After a delay, connect ${context.relativePath} to two other files or skills. ` +
      `Explain a shared invariant, an important difference, and one combined project use.`,
    criteria: context => [
      "Reconstructs the source lesson before reopening it.",
      "Names two specific connections rather than generic similarity.",
      "Includes one tension or tradeoff between the ideas.",
      "Ends with a concrete integration test, design, or portfolio artifact.",
    ],
  },
]);

export async function discoverSourceFiles(rootDirectory) {
  const root = path.resolve(rootDirectory);
  const found = [];

  async function visit(directory) {
    const entries = await readdir(directory, { withFileTypes: true });
    entries.sort((left, right) => left.name.localeCompare(right.name));

    for (const entry of entries) {
      const absolute = path.join(directory, entry.name);
      if (entry.isDirectory()) {
        if (!EXCLUDED_DIRECTORIES.has(entry.name)) {
          await visit(absolute);
        }
        continue;
      }

      if (entry.isFile()) {
        found.push(absolute);
      }
    }
  }

  await visit(root);
  return found.sort((left, right) => left.localeCompare(right));
}

function unique(items) {
  return [...new Set(items.map(item => item.trim()).filter(Boolean))];
}

function markdownCues(text) {
  return [...text.matchAll(/^#{1,4}\s+(.+)$/gm)].map(match => match[1]);
}

function codeCues(text) {
  const symbols = [
    ...text.matchAll(/\b(?:export\s+)?(?:async\s+)?function\s+([A-Za-z_$][\w$]*)/g),
    ...text.matchAll(/\b(?:export\s+)?class\s+([A-Za-z_$][\w$]*)/g),
    ...text.matchAll(/\b(?:export\s+)?const\s+([A-Za-z_$][\w$]*)\s*=/g),
    ...text.matchAll(/\b(?:test|it)\s*\(\s*["'`]([^"'`]+)["'`]/g),
  ];
  return symbols.map(match => match[1]);
}

function yamlCues(text) {
  return [...text.matchAll(/^([A-Za-z0-9_-]+):\s*(?:#.*)?$/gm)].map(
    match => match[1],
  );
}

function jsonCues(text) {
  try {
    const parsed = JSON.parse(text);
    return parsed && typeof parsed === "object" ? Object.keys(parsed) : [];
  } catch {
    return [];
  }
}

export async function extractFileContext(rootDirectory, absolutePath) {
  const text = await readFile(absolutePath, "utf8");
  const extension = path.extname(absolutePath).toLowerCase();
  const relativePath = path.relative(rootDirectory, absolutePath).split(path.sep).join("/");
  const fileName = path.basename(absolutePath);
  const firstMarkdownTitle = markdownCues(text)[0];
  const title = firstMarkdownTitle ?? fileName;

  let extracted = [];
  if (extension === ".md") extracted = markdownCues(text);
  else if ([".js", ".mjs", ".ts", ".tsx", ".cs"].includes(extension)) {
    extracted = codeCues(text);
  } else if (extension === ".json") extracted = jsonCues(text);
  else if ([".yaml", ".yml"].includes(extension)) extracted = yamlCues(text);

  const cues = unique([title, ...extracted, fileName]).slice(0, 12);

  return {
    absolutePath,
    relativePath,
    extension,
    title,
    cues: cues.length > 0 ? cues : [fileName],
    lineCount: text.split(/\r?\n/).length,
    kind: TEXT_EXTENSIONS.has(extension) ? extension.slice(1) || "text" : "asset",
  };
}

function stableCardId(relativePath, blueprintId) {
  const encodedPath = Buffer.from(relativePath, "utf8").toString("base64url");
  return `${encodedPath}.${blueprintId}`;
}

export function buildCards(contexts) {
  return contexts.flatMap(context =>
    CARD_BLUEPRINTS.map((blueprint, index) => ({
      id: stableCardId(context.relativePath, blueprint.id),
      source: context.relativePath,
      sourceTitle: context.title,
      kind: context.kind,
      order: index + 1,
      type: blueprint.id,
      typeName: blueprint.name,
      question: blueprint.question(context),
      criteria: blueprint.criteria(context),
    })),
  );
}

export async function buildDeck(rootDirectory) {
  const files = await discoverSourceFiles(rootDirectory);
  const contexts = await Promise.all(
    files.map(file => extractFileContext(rootDirectory, file)),
  );
  return buildCards(contexts);
}

export function decodeCardSource(cardId) {
  const separator = cardId.lastIndexOf(".");
  if (separator < 1) throw new Error("Invalid card id");
  return Buffer.from(cardId.slice(0, separator), "base64url").toString("utf8");
}
